package com.rootrecord.minecraft.rootskills.storage;

import com.rootrecord.minecraft.rootskills.RootSkillsPlugin;
import com.rootrecord.minecraft.rootskills.api.SkillId;
import com.rootrecord.minecraft.rootskills.model.PlayerSkillsProfile;
import com.rootrecord.minecraft.rootskills.model.SkillProgress;
import com.rootrecord.minecraft.rootskills.model.TalentState;
import org.bukkit.Bukkit;

import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.util.Map;
import java.util.Optional;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;
import java.util.logging.Level;

public final class SkillsRepository {

    private final RootSkillsPlugin plugin;
    private final Database database;
    private final SchemaManager schema;
    private final Map<UUID, PlayerSkillsProfile> cache = new ConcurrentHashMap<>();

    public SkillsRepository(RootSkillsPlugin plugin, Database database, SchemaManager schema) {
        this.plugin = plugin;
        this.database = database;
        this.schema = schema;
    }

    public Optional<PlayerSkillsProfile> find(UUID playerId) {
        if (playerId == null) {
            return Optional.empty();
        }
        return Optional.ofNullable(cache.get(playerId));
    }

    public PlayerSkillsProfile getOrCreate(UUID playerId) {
        return cache.computeIfAbsent(playerId, id -> {
            PlayerSkillsProfile loaded = loadSync(id);
            return loaded != null ? loaded : new PlayerSkillsProfile(id);
        });
    }

    public void loadAsync(UUID playerId, String username, Runnable onLoaded) {
        Bukkit.getScheduler().runTaskAsynchronously(plugin, () -> {
            PlayerSkillsProfile profile = loadSync(playerId);
            if (profile == null) {
                profile = new PlayerSkillsProfile(playerId);
            }
            if (username != null) {
                profile.setUsername(username);
            }
            PlayerSkillsProfile finalProfile = profile;
            Bukkit.getScheduler().runTask(plugin, () -> {
                cache.put(playerId, finalProfile);
                if (plugin.talentManager() != null) {
                    plugin.talentManager().unlockByLevel(finalProfile);
                }
                if (onLoaded != null) {
                    onLoaded.run();
                }
            });
        });
    }

    public PlayerSkillsProfile loadSync(UUID playerId) {
        if (playerId == null || database == null || !database.available()) {
            return null;
        }
        try (Connection c = database.connection()) {
            PlayerSkillsProfile profile = new PlayerSkillsProfile(playerId);
            boolean found = false;
            try (PreparedStatement ps = c.prepareStatement(
                    "SELECT username, class_id, mana, prefs_json, migrated_from, migrated_at FROM "
                            + schema.table("users") + " WHERE uuid=?")) {
                ps.setString(1, playerId.toString());
                try (ResultSet rs = ps.executeQuery()) {
                    if (rs.next()) {
                        found = true;
                        profile.setUsername(rs.getString("username"));
                        profile.setClassId(rs.getString("class_id"));
                        profile.setMana(rs.getDouble("mana"));
                        profile.setPrefsJson(rs.getString("prefs_json"));
                        profile.setMigratedFrom(rs.getString("migrated_from"));
                        long migratedAt = rs.getLong("migrated_at");
                        if (!rs.wasNull()) {
                            profile.setMigratedAt(migratedAt);
                        }
                    }
                }
            }
            try (PreparedStatement ps = c.prepareStatement(
                    "SELECT skill_id, level, xp, prestige, buffs_json FROM "
                            + schema.table("skills") + " WHERE uuid=?")) {
                ps.setString(1, playerId.toString());
                try (ResultSet rs = ps.executeQuery()) {
                    while (rs.next()) {
                        found = true;
                        Optional<SkillId> skill = SkillId.fromString(rs.getString("skill_id"));
                        if (skill.isEmpty()) {
                            continue;
                        }
                        SkillProgress p = profile.skill(skill.get());
                        p.setLevel(rs.getInt("level"));
                        p.setXp(rs.getLong("xp"));
                        p.setPrestige(rs.getInt("prestige"));
                        p.setBuffsJson(rs.getString("buffs_json"));
                        p.setPrestigeBuff(1.0 + (0.05 * p.prestige()));
                    }
                }
            }
            try (PreparedStatement ps = c.prepareStatement(
                    "SELECT talent_id, unlocked, equipped, slot FROM "
                            + schema.table("talents") + " WHERE uuid=?")) {
                ps.setString(1, playerId.toString());
                try (ResultSet rs = ps.executeQuery()) {
                    while (rs.next()) {
                        found = true;
                        TalentState t = profile.talent(rs.getString("talent_id"));
                        t.setUnlocked(rs.getBoolean("unlocked"));
                        t.setEquipped(rs.getBoolean("equipped"));
                        t.setSlot(rs.getInt("slot"));
                    }
                }
            }
            profile.clearDirty();
            return found ? profile : null;
        } catch (Exception ex) {
            plugin.getLogger().log(Level.WARNING, "Load profile failed for " + playerId + ": " + ex.getMessage(), ex);
            return null;
        }
    }

    public void saveAsync(PlayerSkillsProfile profile) {
        if (profile == null) {
            return;
        }
        profile.markDirty();
        Bukkit.getScheduler().runTaskAsynchronously(plugin, () -> saveSync(profile));
    }

    public void saveSync(PlayerSkillsProfile profile) {
        if (profile == null) {
            return;
        }
        cache.put(profile.playerId(), profile);
        if (database == null || !database.available()) {
            profile.clearDirty();
            return;
        }
        try (Connection c = database.connection()) {
            c.setAutoCommit(false);
            long now = System.currentTimeMillis();
            try (PreparedStatement ps = c.prepareStatement(
                    "INSERT INTO " + schema.table("users")
                            + " (uuid, username, class_id, mana, prefs_json, migrated_from, migrated_at, updated_at)"
                            + " VALUES (?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE"
                            + " username=VALUES(username), class_id=VALUES(class_id), mana=VALUES(mana),"
                            + " prefs_json=VALUES(prefs_json), migrated_from=VALUES(migrated_from),"
                            + " migrated_at=VALUES(migrated_at), updated_at=VALUES(updated_at)")) {
                ps.setString(1, profile.playerId().toString());
                ps.setString(2, profile.username());
                ps.setString(3, profile.classId());
                ps.setDouble(4, profile.mana());
                ps.setString(5, profile.prefsJson());
                ps.setString(6, profile.migratedFrom());
                if (profile.migratedAt() == null) {
                    ps.setObject(7, null);
                } else {
                    ps.setLong(7, profile.migratedAt());
                }
                ps.setLong(8, now);
                ps.executeUpdate();
            }
            try (PreparedStatement ps = c.prepareStatement(
                    "INSERT INTO " + schema.table("skills")
                            + " (uuid, skill_id, level, xp, prestige, buffs_json) VALUES (?,?,?,?,?,?)"
                            + " ON DUPLICATE KEY UPDATE level=VALUES(level), xp=VALUES(xp),"
                            + " prestige=VALUES(prestige), buffs_json=VALUES(buffs_json)")) {
                for (SkillProgress sp : profile.skills().values()) {
                    if (sp.level() == 0 && sp.xp() == 0 && sp.prestige() == 0) {
                        continue;
                    }
                    ps.setString(1, profile.playerId().toString());
                    ps.setString(2, sp.skillId().key());
                    ps.setInt(3, sp.level());
                    ps.setLong(4, sp.xp());
                    ps.setInt(5, sp.prestige());
                    ps.setString(6, sp.buffsJson());
                    ps.addBatch();
                }
                ps.executeBatch();
            }
            try (PreparedStatement ps = c.prepareStatement(
                    "INSERT INTO " + schema.table("talents")
                            + " (uuid, talent_id, unlocked, equipped, slot) VALUES (?,?,?,?,?)"
                            + " ON DUPLICATE KEY UPDATE unlocked=VALUES(unlocked),"
                            + " equipped=VALUES(equipped), slot=VALUES(slot)")) {
                for (TalentState t : profile.talents().values()) {
                    if (!t.unlocked() && !t.equipped()) {
                        continue;
                    }
                    ps.setString(1, profile.playerId().toString());
                    ps.setString(2, t.talentId());
                    ps.setBoolean(3, t.unlocked());
                    ps.setBoolean(4, t.equipped());
                    ps.setInt(5, t.slot());
                    ps.addBatch();
                }
                ps.executeBatch();
            }
            c.commit();
            profile.clearDirty();
        } catch (Exception ex) {
            plugin.getLogger().log(Level.WARNING, "Save profile failed for " + profile.playerId() + ": " + ex.getMessage(), ex);
        }
    }

    public void setLevel(UUID playerId, SkillId skill, int level) {
        PlayerSkillsProfile profile = getOrCreate(playerId);
        SkillProgress sp = profile.skill(skill);
        sp.setLevel(level);
        if (plugin.xpService() != null && plugin.xpService().formula() != null) {
            sp.setXp(plugin.xpService().formula().totalXpForLevel(level));
        }
        profile.markDirty();
        saveAsync(profile);
    }

    public void setXp(UUID playerId, SkillId skill, long xp) {
        PlayerSkillsProfile profile = getOrCreate(playerId);
        SkillProgress sp = profile.skill(skill);
        sp.setXp(xp);
        if (plugin.xpService() != null && plugin.xpService().formula() != null) {
            sp.setLevel(plugin.xpService().formula().levelForTotalXp(xp));
        }
        profile.markDirty();
        saveAsync(profile);
    }

    public void unload(UUID playerId) {
        if (playerId == null) {
            return;
        }
        PlayerSkillsProfile profile = cache.remove(playerId);
        if (profile != null) {
            saveSync(profile);
        }
    }

    public void saveAllSync() {
        for (PlayerSkillsProfile profile : cache.values()) {
            saveSync(profile);
        }
    }

    public void mergeSkillGreatest(PlayerSkillsProfile profile, SkillId skill, int level, long xp) {
        SkillProgress sp = profile.skill(skill);
        if (level > sp.level()) {
            sp.setLevel(level);
            sp.setXp(Math.max(xp, sp.xp()));
            profile.markDirty();
        } else if (level == sp.level() && xp > sp.xp()) {
            sp.setXp(xp);
            profile.markDirty();
        }
        // never decrease
    }
}

package com.rootrecord.minecraft.rootskills.storage;

import com.rootrecord.minecraft.rootskills.RootSkillsPlugin;
import com.rootrecord.minecraft.rootskills.api.SkillId;
import com.rootrecord.minecraft.rootskills.model.PlayerSkillsProfile;
import org.bukkit.Bukkit;
import org.bukkit.OfflinePlayer;
import org.bukkit.command.CommandSender;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.sql.Connection;
import java.sql.DatabaseMetaData;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.Statement;
import java.util.ArrayList;
import java.util.HexFormat;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Optional;
import java.util.UUID;
import java.util.logging.Level;

/**
 * Migrates classic mcMMO tables into Root-Skills with GREATEST merge (never decrease).
 */
public final class McMmoMigrator {

    private static final int BATCH = 500;

    /** mcMMO column / skill name → Root SkillId (defense/elytra intentionally absent → 0). */
    private static final Map<String, SkillId> COLUMN_MAP = new LinkedHashMap<>();

    static {
        map("mining", SkillId.MINING);
        map("woodcutting", SkillId.WOODCUTTING);
        map("herbalism", SkillId.HERBALISM);
        map("excavation", SkillId.EXCAVATION);
        map("fishing", SkillId.FISHING);
        map("repair", SkillId.REPAIR);
        map("salvage", SkillId.SALVAGE);
        map("smelting", SkillId.SMELTING);
        map("alchemy", SkillId.ALCHEMY);
        map("taming", SkillId.TAMING);
        map("acrobatics", SkillId.ACROBATICS);
        map("unarmed", SkillId.UNARMED);
        map("swords", SkillId.SWORDS);
        map("axes", SkillId.AXES);
        map("archery", SkillId.ARCHERY);
        map("crossbows", SkillId.CROSSBOWS);
        map("tridents", SkillId.TRIDENTS);
        map("maces", SkillId.MACES);
        map("spears", SkillId.SPEARS);
    }

    private static void map(String key, SkillId id) {
        COLUMN_MAP.put(key.toLowerCase(Locale.ROOT), id);
    }

    private final RootSkillsPlugin plugin;

    public McMmoMigrator(RootSkillsPlugin plugin) {
        this.plugin = plugin;
    }

    public void migrateAll() {
        migrate(Bukkit.getConsoleSender(), false, null);
    }

    public void migrate(CommandSender sender, boolean dryRun, UUID onlyPlayer) {
        Database db = plugin.database();
        if (db == null || !db.available()) {
            sender.sendMessage(plugin.msg("admin.migrate-no-db"));
            return;
        }
        Bukkit.getScheduler().runTaskAsynchronously(plugin, () -> {
            String runId = UUID.randomUUID().toString();
            long started = System.currentTimeMillis();
            int rowsSeen = 0;
            int rowsWritten = 0;
            int conflicts = 0;
            String detail;
            try {
                Result r = runMigration(db, dryRun, onlyPlayer);
                rowsSeen = r.rowsSeen;
                rowsWritten = r.rowsWritten;
                conflicts = r.conflicts;
                detail = r.detail;
                writeLog(db, runId, started, System.currentTimeMillis(), rowsSeen, rowsWritten, conflicts, dryRun,
                        checksum(detail), detail);
                String summary = "mcMMO migrate " + (dryRun ? "DRY-RUN " : "")
                        + "seen=" + rowsSeen + " written=" + rowsWritten + " conflicts=" + conflicts;
                plugin.getLogger().info(summary);
                Bukkit.getScheduler().runTask(plugin, () -> sender.sendMessage(plugin.colorize("&a" + summary)));
            } catch (Exception ex) {
                plugin.getLogger().log(Level.SEVERE, "mcMMO migration failed", ex);
                writeLog(db, runId, started, System.currentTimeMillis(), rowsSeen, rowsWritten, conflicts, dryRun,
                        null, "ERROR: " + ex.getMessage());
                Bukkit.getScheduler().runTask(plugin, () ->
                        sender.sendMessage(plugin.colorize("&cmcMMO migration failed: " + ex.getMessage())));
            }
        });
    }

    private Result runMigration(Database db, boolean dryRun, UUID onlyPlayer) throws Exception {
        try (Connection c = db.connection()) {
            if (!tableExists(c, "mcmmo_users")) {
                return new Result(0, 0, 0, "mcmmo_users missing");
            }
            boolean hasSkills = tableExists(c, "mcmmo_skills");
            boolean hasXp = tableExists(c, "mcmmo_experience");
            if (!hasSkills && !hasXp) {
                return new Result(0, 0, 0, "mcmmo_skills / mcmmo_experience missing");
            }

            List<String> skillCols = filterExistingColumns(c, hasSkills ? "mcmmo_skills" : "mcmmo_experience",
                    new ArrayList<>(COLUMN_MAP.keySet()));
            List<String> xpCols = hasXp
                    ? filterExistingColumns(c, "mcmmo_experience", new ArrayList<>(COLUMN_MAP.keySet()))
                    : List.of();

            boolean usersHaveUuid = columnExists(c, "mcmmo_users", "uuid");
            String userSql = "SELECT id, user" + (usersHaveUuid ? ", uuid" : "") + " FROM mcmmo_users";
            if (onlyPlayer != null && usersHaveUuid) {
                userSql += " WHERE uuid=?";
            }

            int rowsSeen = 0;
            int rowsWritten = 0;
            int conflicts = 0;
            StringBuilder detail = new StringBuilder();

            try (PreparedStatement userPs = c.prepareStatement(userSql)) {
                if (onlyPlayer != null && usersHaveUuid) {
                    userPs.setString(1, onlyPlayer.toString());
                }
                try (ResultSet users = userPs.executeQuery()) {
                    List<UserRow> batch = new ArrayList<>(BATCH);
                    while (users.next()) {
                        int id = users.getInt("id");
                        String name = users.getString("user");
                        UUID uuid = resolveUuid(users, usersHaveUuid, name);
                        if (uuid == null) {
                            continue;
                        }
                        if (onlyPlayer != null && !onlyPlayer.equals(uuid)) {
                            continue;
                        }
                        batch.add(new UserRow(id, name, uuid));
                        if (batch.size() >= BATCH) {
                            Counts cnt = processBatch(c, batch, hasSkills, hasXp, skillCols, xpCols, dryRun);
                            rowsSeen += cnt.seen;
                            rowsWritten += cnt.written;
                            conflicts += cnt.conflicts;
                            batch.clear();
                        }
                    }
                    if (!batch.isEmpty()) {
                        Counts cnt = processBatch(c, batch, hasSkills, hasXp, skillCols, xpCols, dryRun);
                        rowsSeen += cnt.seen;
                        rowsWritten += cnt.written;
                        conflicts += cnt.conflicts;
                    }
                }
            }
            detail.append("skillsCols=").append(skillCols.size())
                    .append(";xpCols=").append(xpCols.size())
                    .append(";dryRun=").append(dryRun);
            return new Result(rowsSeen, rowsWritten, conflicts, detail.toString());
        }
    }

    private Counts processBatch(
            Connection c,
            List<UserRow> batch,
            boolean hasSkills,
            boolean hasXp,
            List<String> skillCols,
            List<String> xpCols,
            boolean dryRun) throws Exception {
        int seen = 0;
        int written = 0;
        int conflicts = 0;
        for (UserRow row : batch) {
            seen++;
            Map<SkillId, Integer> levels = new LinkedHashMap<>();
            Map<SkillId, Long> xps = new LinkedHashMap<>();
            if (hasSkills && !skillCols.isEmpty()) {
                readWideRow(c, "mcmmo_skills", row.id, skillCols, levels, null);
            }
            if (hasXp && !xpCols.isEmpty()) {
                readWideRow(c, "mcmmo_experience", row.id, xpCols, null, xps);
            }
            // Also try vertical layout: skill / level columns
            if (levels.isEmpty()) {
                readVertical(c, row.id, levels, xps);
            }

            PlayerSkillsProfile existing = plugin.repository().loadSync(row.uuid);
            if (existing == null) {
                existing = new PlayerSkillsProfile(row.uuid);
            }
            existing.setUsername(row.name);
            boolean changed = false;
            for (Map.Entry<SkillId, Integer> e : levels.entrySet()) {
                int before = existing.skill(e.getKey()).level();
                long xp = xps.getOrDefault(e.getKey(), 0L);
                plugin.repository().mergeSkillGreatest(existing, e.getKey(), e.getValue(), xp);
                int after = existing.skill(e.getKey()).level();
                if (after != before || existing.dirty()) {
                    changed = true;
                    if (before > 0 && after == before && xp > 0) {
                        // same level higher xp still counts as write, not conflict
                    } else if (before > e.getValue()) {
                        conflicts++;
                    }
                }
            }
            // defense / elytra stay 0 unless already present
            if (changed) {
                existing.setMigratedFrom("mcmmo");
                existing.setMigratedAt(System.currentTimeMillis());
                if (!dryRun) {
                    plugin.repository().saveSync(existing);
                    written++;
                } else {
                    written++; // counted as would-write
                }
            }
        }
        return new Counts(seen, written, conflicts);
    }

    private void readWideRow(
            Connection c,
            String table,
            int userId,
            List<String> cols,
            Map<SkillId, Integer> levels,
            Map<SkillId, Long> xps) throws Exception {
        StringBuilder sb = new StringBuilder("SELECT ");
        for (int i = 0; i < cols.size(); i++) {
            if (i > 0) {
                sb.append(',');
            }
            sb.append('`').append(cols.get(i)).append('`');
        }
        sb.append(" FROM ").append(table).append(" WHERE user_id=?");
        try (PreparedStatement ps = c.prepareStatement(sb.toString())) {
            ps.setInt(1, userId);
            try (ResultSet rs = ps.executeQuery()) {
                if (!rs.next()) {
                    return;
                }
                for (String col : cols) {
                    SkillId skill = COLUMN_MAP.get(col.toLowerCase(Locale.ROOT));
                    if (skill == null) {
                        continue;
                    }
                    if (levels != null) {
                        levels.put(skill, rs.getInt(col));
                    }
                    if (xps != null) {
                        xps.put(skill, rs.getLong(col));
                    }
                }
            }
        } catch (Exception ex) {
            // try alternate PK column name
            try (PreparedStatement ps = c.prepareStatement(
                    sb.toString().replace("user_id=?", "id=?"))) {
                ps.setInt(1, userId);
                try (ResultSet rs = ps.executeQuery()) {
                    if (!rs.next()) {
                        return;
                    }
                    for (String col : cols) {
                        SkillId skill = COLUMN_MAP.get(col.toLowerCase(Locale.ROOT));
                        if (skill == null) {
                            continue;
                        }
                        if (levels != null) {
                            levels.put(skill, rs.getInt(col));
                        }
                        if (xps != null) {
                            xps.put(skill, rs.getLong(col));
                        }
                    }
                }
            }
        }
    }

    private void readVertical(Connection c, int userId, Map<SkillId, Integer> levels, Map<SkillId, Long> xps)
            throws Exception {
        if (!tableExists(c, "mcmmo_skills")) {
            return;
        }
        // Some forks: user_id, skill, skill_value / xp
        if (!columnExists(c, "mcmmo_skills", "skill")) {
            return;
        }
        String valueCol = columnExists(c, "mcmmo_skills", "skill_value") ? "skill_value"
                : (columnExists(c, "mcmmo_skills", "level") ? "level" : null);
        if (valueCol == null) {
            return;
        }
        try (PreparedStatement ps = c.prepareStatement(
                "SELECT skill, " + valueCol + " FROM mcmmo_skills WHERE user_id=?")) {
            ps.setInt(1, userId);
            try (ResultSet rs = ps.executeQuery()) {
                while (rs.next()) {
                    SkillId skill = COLUMN_MAP.get(rs.getString("skill").toLowerCase(Locale.ROOT));
                    if (skill != null) {
                        levels.put(skill, rs.getInt(2));
                    }
                }
            }
        }
    }

    private UUID resolveUuid(ResultSet users, boolean hasUuid, String name) throws Exception {
        if (hasUuid) {
            String raw = users.getString("uuid");
            if (raw != null && !raw.isBlank()) {
                try {
                    return UUID.fromString(raw.contains("-") ? raw
                            : raw.replaceFirst(
                            "(\\w{8})(\\w{4})(\\w{4})(\\w{4})(\\w{12})",
                            "$1-$2-$3-$4-$5"));
                } catch (IllegalArgumentException ignored) {
                }
            }
        }
        if (name == null || name.isBlank()) {
            return null;
        }
        OfflinePlayer offline = Bukkit.getOfflinePlayer(name);
        return offline.getUniqueId();
    }

    private void writeLog(
            Database db,
            String runId,
            long started,
            long finished,
            int seen,
            int written,
            int conflicts,
            boolean dryRun,
            String checksum,
            String detail) {
        try (Connection c = db.connection();
             PreparedStatement ps = c.prepareStatement(
                     "INSERT INTO " + plugin.schemaManager().table("migration_log")
                             + " (run_id, started_at, finished_at, rows_seen, rows_written, conflicts, dry_run, checksum, detail)"
                             + " VALUES (?,?,?,?,?,?,?,?,?)")) {
            ps.setString(1, runId);
            ps.setLong(2, started);
            ps.setLong(3, finished);
            ps.setInt(4, seen);
            ps.setInt(5, written);
            ps.setInt(6, conflicts);
            ps.setBoolean(7, dryRun);
            ps.setString(8, checksum);
            ps.setString(9, detail);
            ps.executeUpdate();
        } catch (Exception ex) {
            plugin.getLogger().warning("migration_log write failed: " + ex.getMessage());
        }
    }

    private static boolean tableExists(Connection c, String table) throws Exception {
        DatabaseMetaData md = c.getMetaData();
        try (ResultSet rs = md.getTables(c.getCatalog(), null, table, null)) {
            if (rs.next()) {
                return true;
            }
        }
        try (ResultSet rs = md.getTables(c.getCatalog(), null, table.toUpperCase(Locale.ROOT), null)) {
            return rs.next();
        }
    }

    private static boolean columnExists(Connection c, String table, String column) throws Exception {
        DatabaseMetaData md = c.getMetaData();
        try (ResultSet rs = md.getColumns(c.getCatalog(), null, table, column)) {
            if (rs.next()) {
                return true;
            }
        }
        try (ResultSet rs = md.getColumns(c.getCatalog(), null, table, column.toUpperCase(Locale.ROOT))) {
            return rs.next();
        }
    }

    private static List<String> filterExistingColumns(Connection c, String table, List<String> wanted)
            throws Exception {
        List<String> out = new ArrayList<>();
        for (String col : wanted) {
            if (columnExists(c, table, col)) {
                out.add(col);
            }
        }
        return out;
    }

    private static String checksum(String detail) {
        try {
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            byte[] dig = md.digest((detail == null ? "" : detail).getBytes(StandardCharsets.UTF_8));
            return HexFormat.of().formatHex(dig).substring(0, 32);
        } catch (Exception ex) {
            return null;
        }
    }

    private record UserRow(int id, String name, UUID uuid) {}

    private record Counts(int seen, int written, int conflicts) {}

    private record Result(int rowsSeen, int rowsWritten, int conflicts, String detail) {}
}

package com.rootrecord.minecraft.rootskills.skills;

import com.rootrecord.minecraft.rootskills.RootSkillsPlugin;
import com.rootrecord.minecraft.rootskills.api.SkillId;
import com.rootrecord.minecraft.rootskills.api.events.RootSkillsLevelUpEvent;
import com.rootrecord.minecraft.rootskills.api.events.RootSkillsXpGainEvent;
import com.rootrecord.minecraft.rootskills.model.PlayerSkillsProfile;
import com.rootrecord.minecraft.rootskills.model.SkillProgress;
import com.rootrecord.minecraft.rootskills.storage.SkillsRepository;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import org.bukkit.Bukkit;
import org.bukkit.entity.Player;

import java.util.HashMap;
import java.util.Map;
import java.util.UUID;

public final class XpService {

    private final RootSkillsPlugin plugin;
    private final SkillsRepository repository;
    private XpFormula formula;

    public XpService(RootSkillsPlugin plugin, SkillsRepository repository, XpFormula formula) {
        this.plugin = plugin;
        this.repository = repository;
        this.formula = formula;
    }

    public void setFormula(XpFormula formula) {
        this.formula = formula;
    }

    public XpFormula formula() {
        return formula;
    }

    public void addXp(UUID playerId, SkillId skill, long rawAmount) {
        addXp(playerId, skill, rawAmount, true);
    }

    public void addXp(UUID playerId, SkillId skill, long rawAmount, boolean shareParty) {
        if (playerId == null || skill == null || rawAmount <= 0) {
            return;
        }

        double mult = formula.globalXpMultiplier();
        mult *= plugin.getConfig().getDouble("skill-multipliers." + skill.key(), 1.0);
        if (plugin.boosterManager() != null) {
            mult *= plugin.boosterManager().xpMultiplier(playerId, skill);
        }
        if (plugin.classManager() != null) {
            PlayerSkillsProfile tmp = repository.getOrCreate(playerId);
            mult *= plugin.classManager().skillXpMultiplier(tmp.classId(), skill);
        }
        PlayerSkillsProfile profile = repository.getOrCreate(playerId);
        SkillProgress progress = profile.skill(skill);
        mult *= progress.prestigeBuff();

        long amount = Math.max(0L, (long) Math.floor(rawAmount * mult));
        if (amount <= 0) {
            return;
        }

        Player player = Bukkit.getPlayer(playerId);
        if (player != null) {
            RootSkillsXpGainEvent event = new RootSkillsXpGainEvent(player, skill, amount);
            Bukkit.getPluginManager().callEvent(event);
            if (event.isCancelled() || event.getAmount() <= 0) {
                return;
            }
            amount = event.getAmount();
        }

        int oldLevel = progress.level();
        progress.addXp(amount);
        int newLevel = formula.levelForTotalXp(progress.xp());
        if (newLevel > oldLevel) {
            progress.setLevel(newLevel);
            if (player != null) {
                for (int lvl = oldLevel + 1; lvl <= newLevel; lvl++) {
                    Bukkit.getPluginManager().callEvent(new RootSkillsLevelUpEvent(player, skill, lvl - 1, lvl));
                }
                player.sendMessage(plugin.msg("skills.level-up")
                        .replace("{skill}", skill.key())
                        .replace("{level}", Integer.toString(newLevel)));
                if (plugin.talentManager() != null) {
                    plugin.talentManager().unlockByLevel(profile);
                }
                if (plugin.triggerBus() != null) {
                    Map<String, Object> ctx = new HashMap<>();
                    ctx.put("skill", skill.key());
                    ctx.put("level", newLevel);
                    plugin.triggerBus().fire(player, "on_level_up", ctx);
                }
            }
        }
        profile.markDirty();
        repository.saveAsync(profile);

        if (player != null) {
            long next = formula.xpToNext(progress.level());
            long floor = formula.totalXpForLevel(progress.level());
            long into = Math.max(0L, progress.xp() - floor);
            player.sendActionBar(Component.text(
                    "+" + amount + " " + skill.key() + " XP  (" + into + "/" + next + ")",
                    NamedTextColor.GOLD));
        }

        if (shareParty && plugin.partyManager() != null && player != null) {
            plugin.partyManager().shareXp(player, skill, amount);
        }
    }
}

