import org.bukkit.event.entity.EntityTameEvent;
import org.bukkit.event.inventory.BrewEvent;
import org.bukkit.event.inventory.FurnaceSmeltEvent;
import org.bukkit.event.inventory.PrepareAnvilEvent;
import org.bukkit.event.player.PlayerFishEvent;
import org.bukkit.event.player.PlayerMoveEvent;
import org.bukkit.inventory.ItemStack;
import org.bukkit.metadata.FixedMetadataValue;
import org.bukkit.projectiles.ProjectileSource;

import java.util.Locale;
import java.util.Map;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;

import com.rootrecord.minecraft.rootskills.api.SkillId;

public final class SkillListenerRegistrar implements Listener {

    private static final String META_SPAWN_REASON = "rootskills_spawn_reason";

    private final RootSkillsPlugin plugin;
    private final Map<String, Long> recentPlaced = new ConcurrentHashMap<>();
    private final Map<UUID, Double> elytraDistance = new ConcurrentHashMap<>();

    public SkillListenerRegistrar(RootSkillsPlugin plugin) {
        this.plugin = plugin;
    }

    public void registerAll() {
        plugin.getServer().getPluginManager().registerEvents(this, plugin);
        plugin.getLogger().info("Skill listeners registered");
    }

    public void register(Listener listener) {
        if (listener != null) {
            plugin.getServer().getPluginManager().registerEvents(listener, plugin);
        }
    }

    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onPlace(BlockPlaceEvent event) {
        if (!plugin.getConfig().getBoolean("anti-farm.track-recent-blocks", true)
                && !plugin.getConfig().getBoolean("anti-farm.prevent-place-and-break", true)) {
            return;
        }
        Block b = event.getBlockPlaced();
        recentPlaced.put(blockKey(b), System.currentTimeMillis());
    }

    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onSpawn(CreatureSpawnEvent event) {
        event.getEntity().setMetadata(META_SPAWN_REASON,
                new FixedMetadataValue(plugin, event.getSpawnReason().name()));
    }

    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onBreak(BlockBreakEvent event) {
        Player player = event.getPlayer();
        if (!canEarn(player) || deniedRegion(player)) {
            return;
        }
        Block block = event.getBlock();
        if (isRecentlyPlaced(block)) {
            return;
        }
        Material type = block.getType();
        SkillId skill = skillForBlock(type);
        if (skill == null) {
            return;
        }
        long xp = xpForBlock(type);
        if (plugin.abilitySessions() != null && plugin.abilitySessions().has(player.getUniqueId(), "break_bonus")) {
            if (Math.random() < 0.25) {
                block.getWorld().dropItemNaturally(block.getLocation(), new ItemStack(type));
            }
        }
        plugin.xpService().addXp(player.getUniqueId(), skill, xp);
        plugin.triggerBus().fire(player, "on_block_break", Map.of("material", type.name(), "skill", skill.key()));
        if (skill == SkillId.HERBALISM) {
            plugin.triggerBus().fire(player, "on_crop_harvest", Map.of("material", type.name()));
        }
    }

    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onDamage(EntityDamageByEntityEvent event) {
        Player player = damagerPlayer(event);
        if (player == null || !canEarn(player) || deniedRegion(player)) {
            return;
        }
        if (!(event.getEntity() instanceof LivingEntity)) {
            return;
        }
        if (spawnerZero(event.getEntity())) {
            return;
        }
        SkillId skill = skillForWeapon(player);
        if (skill == null) {
            return;
        }
        long xp = Math.max(1L, (long) Math.ceil(event.getFinalDamage()));
        plugin.xpService().addXp(player.getUniqueId(), skill, xp);
        plugin.triggerBus().fire(player, "on_entity_damage", Map.of("skill", skill.key()));
    }

    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onDeath(EntityDeathEvent event) {
        Player killer = event.getEntity().getKiller();
        if (killer == null || !canEarn(killer) || deniedRegion(killer)) {
            return;
        }
        if (spawnerZero(event.getEntity())) {
            return;
        }
        SkillId skill = skillForWeapon(killer);
        if (skill == null) {
            skill = SkillId.UNARMED;
        }
        plugin.xpService().addXp(killer.getUniqueId(), skill, 10L);
        plugin.triggerBus().fire(killer, "on_entity_kill", Map.of("skill", skill.key()));
    }

    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onFall(EntityDamageEvent event) {
        if (!(event.getEntity() instanceof Player player)) {
            return;
        }
        if (!canEarn(player) || deniedRegion(player)) {
            return;
        }
        if (event.getCause() == EntityDamageEvent.DamageCause.FALL) {
            if (plugin.getConfig().getBoolean("anti-farm.prevent-acrobatics-afk", true)
                    && event.getFinalDamage() < 1.0) {
                return;
            }
            long xp = Math.max(1L, (long) Math.ceil(event.getFinalDamage() * 2));
            plugin.xpService().addXp(player.getUniqueId(), SkillId.ACROBATICS, xp);
            plugin.triggerBus().fire(player, "on_fall", Map.of());
        }
        if (event.getFinalDamage() > 0) {
            plugin.xpService().addXp(player.getUniqueId(), SkillId.DEFENSE,
                    Math.max(1L, (long) Math.ceil(event.getFinalDamage())));
            plugin.triggerBus().fire(player, "on_player_damage", Map.of());
        }
    }

    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onFish(PlayerFishEvent event) {
        if (event.getState() != PlayerFishEvent.State.CAUGHT_FISH) {
            return;
        }
        Player player = event.getPlayer();
        if (!canEarn(player) || deniedRegion(player)) {
            return;
        }
        plugin.xpService().addXp(player.getUniqueId(), SkillId.FISHING, 25L);
        plugin.triggerBus().fire(player, "on_fish_catch", Map.of());
    }

    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onBrew(BrewEvent event) {
        // Best-effort: award nearest player in radius
        Location loc = event.getBlock().getLocation();
        Player nearest = nearestPlayer(loc, 5);
        if (nearest == null || !canEarn(nearest) || deniedRegion(nearest)) {
            return;
        }
        if (plugin.getConfig().getBoolean("anti-farm.prevent-alchemy-exploit", true)
                && isRecentlyPlaced(event.getBlock())) {
            return;
        }
        plugin.xpService().addXp(nearest.getUniqueId(), SkillId.ALCHEMY, 20L);
        plugin.triggerBus().fire(nearest, "on_brew", Map.of());
    }

    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onTame(EntityTameEvent event) {
        if (!(event.getOwner() instanceof Player player)) {
            return;
        }
        if (!canEarn(player) || deniedRegion(player)) {
            return;
        }
        plugin.xpService().addXp(player.getUniqueId(), SkillId.TAMING, 50L);
        plugin.triggerBus().fire(player, "on_tame", Map.of());
    }

    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onSmelt(FurnaceSmeltEvent event) {
        Location loc = event.getBlock().getLocation();
        Player nearest = nearestPlayer(loc, 5);
        if (nearest == null || !canEarn(nearest) || deniedRegion(nearest)) {
            return;
        }
        plugin.xpService().addXp(nearest.getUniqueId(), SkillId.SMELTING, 5L);
        plugin.triggerBus().fire(nearest, "on_smelt", Map.of());
    }

    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onAnvil(PrepareAnvilEvent event) {
        if (!(event.getView().getPlayer() instanceof Player player)) {
            return;
        }
        ItemStack result = event.getResult();
        if (result == null || result.getType().isAir()) {
            return;
        }
        // Light repair XP when result has higher durability potential — award small XP
        if (!canEarn(player)) {
            return;
        }
        plugin.xpService().addXp(player.getUniqueId(), SkillId.REPAIR, 2L);
        plugin.triggerBus().fire(player, "on_repair", Map.of());
    }

    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onBreed(EntityBreedEvent event) {
        if (!(event.getBreeder() instanceof Player player)) {
            return;
        }
        double mult = plugin.getConfig().getDouble("anti-farm.breeding-multiplier", 1.0);
        if (mult <= 0 || !canEarn(player)) {
            return;
        }
        plugin.xpService().addXp(player.getUniqueId(), SkillId.TAMING, Math.max(1L, (long) (15 * mult)));
    }

    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onMove(PlayerMoveEvent event) {
        Player player = event.getPlayer();
        if (!player.isGliding() || event.getTo() == null || event.getFrom() == null) {
            return;
        }
        if (!canEarn(player)) {
            return;
        }
        double dist = event.getFrom().distance(event.getTo());
        if (dist <= 0) {
            return;
        }
        double acc = elytraDistance.merge(player.getUniqueId(), dist, Double::sum);
        if (acc >= 10.0) {
            elytraDistance.put(player.getUniqueId(), acc - 10.0);
            plugin.xpService().addXp(player.getUniqueId(), SkillId.ELYTRA, 2L);
            plugin.triggerBus().fire(player, "on_elytra_boost", Map.of());
        }
    }

    private boolean canEarn(Player player) {
        return player != null
                && player.getGameMode() != GameMode.CREATIVE
                && player.getGameMode() != GameMode.SPECTATOR
                && player.hasPermission("rootskills.use");
    }

    private boolean deniedRegion(Player player) {
        return RegionGuard.isDenied(plugin, player);
    }

    private boolean isRecentlyPlaced(Block block) {
        if (!plugin.getConfig().getBoolean("anti-farm.prevent-place-and-break", true)
                && !plugin.getConfig().getBoolean("anti-farm.track-recent-blocks", true)) {
            return false;
        }
        String key = blockKey(block);
        Long when = recentPlaced.get(key);
        if (when == null) {
            return false;
        }
        long ttl = plugin.getConfig().getLong("anti-farm.recent-block-ttl-seconds", 30) * 1000L;
        if (System.currentTimeMillis() - when > ttl) {
            recentPlaced.remove(key);
            return false;
        }
        return true;
    }

    private boolean spawnerZero(Entity entity) {
        double mult = plugin.getConfig().getDouble("anti-farm.mobspawners-multiplier", 0.0);
        if (mult > 0) {
            return false;
        }
        if (!entity.hasMetadata(META_SPAWN_REASON)) {
            return false;
        }
        String reason = entity.getMetadata(META_SPAWN_REASON).getFirst().asString();
        if ("SPAWNER".equals(reason) || "SPAWNER_EGG".equals(reason)) {
            return true;
        }
        if ("NETHER_PORTAL".equals(reason)
                && plugin.getConfig().getDouble("anti-farm.nether-portal-multiplier", 0.0) <= 0) {
            return true;
        }
        return "EGG".equals(reason)
                && plugin.getConfig().getDouble("anti-farm.eggs-multiplier", 0.0) <= 0;
    }

    private static String blockKey(Block b) {
        return b.getWorld().getUID() + ":" + b.getX() + ":" + b.getY() + ":" + b.getZ();
    }

    private static Player nearestPlayer(Location loc, double radius) {
        Player best = null;
        double bestDist = radius * radius;
        for (Player p : loc.getWorld().getPlayers()) {
            double d = p.getLocation().distanceSquared(loc);
            if (d <= bestDist) {
                bestDist = d;
                best = p;
            }
        }
        return best;
    }

    private static Player damagerPlayer(EntityDamageByEntityEvent event) {
        if (event.getDamager() instanceof Player p) {
            return p;
        }
        if (event.getDamager() instanceof org.bukkit.entity.Projectile proj) {
            ProjectileSource src = proj.getShooter();
            if (src instanceof Player p) {
                return p;
            }
        }
        return null;
    }

    private static SkillId skillForWeapon(Player player) {
        ItemStack hand = player.getInventory().getItemInMainHand();
        Material m = hand == null ? Material.AIR : hand.getType();
        String n = m.name();
        if (n.endsWith("_SWORD")) {
            return SkillId.SWORDS;
        }
        if (n.endsWith("_AXE")) {
            return SkillId.AXES;
        }
        if (m == Material.BOW) {
            return SkillId.ARCHERY;
        }
        if (m == Material.CROSSBOW) {
            return SkillId.CROSSBOWS;
        }
        if (m == Material.TRIDENT) {
            return SkillId.TRIDENTS;
        }
        if (m == Material.MACE) {
            return SkillId.MACES;
        }
        if (n.contains("SPEAR")) {
            return SkillId.SPEARS;
        }
        if (m == Material.AIR) {
            return SkillId.UNARMED;
        }
        return SkillId.UNARMED;
    }

    private static SkillId skillForBlock(Material type) {
        String n = type.name();
        if (n.contains("ORE") || n.contains("DEEPSLATE") && (n.contains("ORE") || n.equals("ANCIENT_DEBRIS"))
                || type == Material.ANCIENT_DEBRIS || type == Material.STONE || type == Material.COBBLESTONE
                || type == Material.NETHERRACK || type == Material.END_STONE || type == Material.OBSIDIAN
                || n.contains("DEEPSLATE") && !n.contains("ORE")) {
            if (isLog(type)) {
                return SkillId.WOODCUTTING;
            }
            if (isDirt(type)) {
                return SkillId.EXCAVATION;
            }
            if (isCrop(type)) {
                return SkillId.HERBALISM;
            }
            if (n.contains("ORE") || type == Material.ANCIENT_DEBRIS || type == Material.STONE
                    || type == Material.COBBLESTONE || type == Material.NETHERRACK
                    || type == Material.END_STONE || type == Material.OBSIDIAN
                    || n.endsWith("_DEEPSLATE") || n.equals("DEEPSLATE") || n.equals("COBBLED_DEEPSLATE")
                    || n.contains("DEEPSLATE")) {
                return SkillId.MINING;
            }
        }
        if (isLog(type)) {
            return SkillId.WOODCUTTING;
        }
        if (isDirt(type)) {
            return SkillId.EXCAVATION;
        }
        if (isCrop(type)) {
            return SkillId.HERBALISM;
        }
        if (n.contains("ORE") || type == Material.ANCIENT_DEBRIS) {
            return SkillId.MINING;
        }
        return null;
    }

    private static boolean isLog(Material type) {
        String n = type.name();
        return n.endsWith("_LOG") || n.endsWith("_STEM") || n.equals("MANGROVE_ROOTS");
    }

    private static boolean isDirt(Material type) {
        return switch (type) {
            case DIRT, GRASS_BLOCK, SAND, RED_SAND, GRAVEL, CLAY, SOUL_SAND, SOUL_SOIL,
                 MYCELIUM, PODZOL, MUD, MUDDY_MANGROVE_ROOTS, COARSE_DIRT, ROOTED_DIRT -> true;
            default -> false;
        };
    }

    private static boolean isCrop(Material type) {
        String n = type.name().toLowerCase(Locale.ROOT);
        return type == Material.WHEAT || type == Material.CARROTS || type == Material.POTATOES
                || type == Material.BEETROOTS || type == Material.NETHER_WART || type == Material.COCOA
                || type == Material.SUGAR_CANE || type == Material.CACTUS || type == Material.MELON
                || type == Material.PUMPKIN || type == Material.BAMBOO || type == Material.SWEET_BERRY_BUSH
                || n.contains("mushroom") || type == Material.KELP || type == Material.KELP_PLANT;
    }

    private static long xpForBlock(Material type) {
        String n = type.name();
        if (n.contains("DIAMOND") || n.contains("EMERALD") || type == Material.ANCIENT_DEBRIS) {
            return 40L;
        }
        if (n.contains("GOLD") || n.contains("IRON") || n.contains("LAPIS") || n.contains("REDSTONE")
                || n.contains("COPPER") || n.contains("QUARTZ") || n.contains("COAL")) {
            return 15L;
        }
        if (isLog(type)) {
            return 8L;
        }
        if (isCrop(type)) {
            return 6L;
        }
        if (isDirt(type)) {
            return 4L;
        }
        return 5L;
    }
}

package com.rootrecord.minecraft.rootskills.skills;

import com.rootrecord.minecraft.rootskills.RootSkillsPlugin;
import org.bukkit.Bukkit;
import org.bukkit.entity.Player;
import org.bukkit.plugin.Plugin;

/**
 * Best-effort Towny / Root-Claims denial checks via reflection — never hard-fails.
 */
public final class RegionGuard {

    private RegionGuard() {}

    public static boolean isDenied(RootSkillsPlugin plugin, Player player) {
        if (player == null) {
            return false;
        }
        try {
            if (isTownyDenied(player)) {
                return true;
            }
        } catch (Throwable ignored) {
        }
        try {
            if (isClaimsDenied(plugin, player)) {
                return true;
            }
        } catch (Throwable ignored) {
        }
        return false;
    }

    private static boolean isTownyDenied(Player player) throws Exception {
        Plugin towny = Bukkit.getPluginManager().getPlugin("Towny");
        if (towny == null || !towny.isEnabled()) {
            return false;
        }
        Class<?> api = Class.forName("com.palmergames.bukkit.towny.TownyAPI");
        Object instance = api.getMethod("getInstance").invoke(null);
        Boolean wilderness = (Boolean) api.getMethod("isWilderness", org.bukkit.Location.class)
                .invoke(instance, player.getLocation());
        if (Boolean.TRUE.equals(wilderness)) {
            return false;
        }
        // If in a town and player is not a resident of that town, skip XP (soft PvP/plot guard)
        Object town = api.getMethod("getTown", org.bukkit.Location.class).invoke(instance, player.getLocation());
        if (town == null) {
            return false;
        }
        Object resident = api.getMethod("getResident", Player.class).invoke(instance, player);
        if (resident == null) {
            return true;
        }
        Object resTown = resident.getClass().getMethod("getTownOrNull").invoke(resident);
        return resTown == null || !resTown.equals(town);
    }

    private static boolean isClaimsDenied(RootSkillsPlugin plugin, Player player) throws Exception {
        Plugin claims = Bukkit.getPluginManager().getPlugin("Root-Claims");
        if (claims == null) {
            claims = Bukkit.getPluginManager().getPlugin("RootClaims");
        }
        if (claims == null || !claims.isEnabled()) {
            return false;
        }
        // Soft: look for a static canBuild(Player, Location) or similar
        for (String className : new String[] {
                "com.rootrecord.minecraft.rootclaims.ClaimsAPI",
                "com.rootrecord.minecraft.claims.ClaimsAPI"
        }) {
            try {
                Class<?> api = Class.forName(className);
                Object inst = null;
                try {
                    inst = api.getMethod("get").invoke(null);
                } catch (NoSuchMethodException ignored) {
                    try {
                        inst = api.getMethod("getInstance").invoke(null);
                    } catch (NoSuchMethodException ignored2) {
                    }
                }
                Object target = inst != null ? inst : api;
                try {
                    Object allowed = (inst != null ? api : Class.forName(className))
                            .getMethod("canBuild", Player.class, org.bukkit.Location.class)
                            .invoke(inst != null ? inst : null, player, player.getLocation());
                    if (allowed instanceof Boolean b && !b) {
                        return true;
                    }
                } catch (NoSuchMethodException ignored) {
                }
            } catch (ClassNotFoundException ignored) {
            }
        }
        return false;
    }
}

package com.rootrecord.minecraft.rootskills.talents;

import com.rootrecord.minecraft.rootskills.api.SkillId;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;

public final class TalentDefinition {

    private final String id;
    private final String displayName;
    private final String description;
    private final SkillId skill;
    private final int unlockLevel;
    private final int maxRank;
    private final double manaCost;
    private final int cooldownSeconds;
    private final int durationSeconds;
    private final List<String> triggers;
    private final List<Map<String, Object>> effects;
    private final List<Map<String, Object>> conditions;

    public TalentDefinition(
            String id,
            String displayName,
            String description,
            SkillId skill,
            int unlockLevel,
            int maxRank,
            double manaCost,
            int cooldownSeconds,
            int durationSeconds,
            List<String> triggers,
            List<Map<String, Object>> effects,
            List<Map<String, Object>> conditions) {
        this.id = id;
        this.displayName = displayName;
        this.description = description;
        this.skill = skill;
        this.unlockLevel = unlockLevel;
        this.maxRank = Math.max(1, maxRank);
        this.manaCost = manaCost;
        this.cooldownSeconds = cooldownSeconds;
        this.durationSeconds = durationSeconds;
        this.triggers = triggers == null ? List.of() : List.copyOf(triggers);
        this.effects = effects == null ? List.of() : List.copyOf(effects);
        this.conditions = conditions == null ? List.of() : List.copyOf(conditions);
    }

    public String id() {
        return id;
    }

    public String displayName() {
        return displayName;
    }

    public String description() {
        return description;
    }

    public SkillId skill() {
        return skill;
    }

    public int unlockLevel() {
        return unlockLevel;
    }

    public int maxRank() {
        return maxRank;
    }

    public double manaCost() {
        return manaCost;
    }

    public int cooldownSeconds() {
        return cooldownSeconds;
    }

    public int durationSeconds() {
        return durationSeconds;
    }

    public List<String> triggers() {
        return triggers;
    }

    public List<Map<String, Object>> effects() {
        return effects;
    }

    public List<Map<String, Object>> conditions() {
        return conditions;
    }

    public List<Map<String, Object>> mutableEffects() {
        List<Map<String, Object>> copy = new ArrayList<>();
        for (Map<String, Object> e : effects) {
            copy.add(e);
        }
        return copy;
    }
}

package com.rootrecord.minecraft.rootskills.talents;

import com.rootrecord.minecraft.rootskills.RootSkillsPlugin;
import com.rootrecord.minecraft.rootskills.api.SkillId;
import com.rootrecord.minecraft.rootskills.api.events.RootSkillsTalentTriggerEvent;
import com.rootrecord.minecraft.rootskills.model.PlayerSkillsProfile;
import com.rootrecord.minecraft.rootskills.model.TalentState;
import org.bukkit.Bukkit;
import org.bukkit.configuration.ConfigurationSection;
import org.bukkit.configuration.file.YamlConfiguration;
import org.bukkit.entity.Player;

import java.io.File;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collection;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Optional;
import java.util.logging.Level;

public final class TalentManager {

    private final RootSkillsPlugin plugin;
    private final Map<String, TalentDefinition> talents = new LinkedHashMap<>();

    public TalentManager(RootSkillsPlugin plugin) {
        this.plugin = plugin;
    }

    public void load() {
        talents.clear();
        File dir = new File(plugin.getDataFolder(), "talents");
        if (!dir.exists()) {
            dir.mkdirs();
            // extract bundled examples
            for (String name : List.of(
                    "mining_super_breaker.yml",
                    "woodcutting_tree_feller.yml",
                    "excavation_giga_drill.yml",
                    "swords_serrated_strikes.yml",
                    "archery_skill_shot.yml")) {
                if (!new File(dir, name).exists()) {
                    plugin.saveResource("talents/" + name, false);
                }
            }
        }
        File[] files = dir.listFiles((d, n) -> n.endsWith(".yml"));
        if (files != null) {
            for (File file : files) {
                try {
                    loadFile(YamlConfiguration.loadConfiguration(file));
                } catch (Exception ex) {
                    plugin.getLogger().log(Level.WARNING, "Talent load failed: " + file.getName(), ex);
                }
            }
        }
        if (talents.isEmpty()) {
            // fallback classpath
            for (String name : List.of(
                    "mining_super_breaker.yml",
                    "woodcutting_tree_feller.yml",
                    "excavation_giga_drill.yml",
                    "swords_serrated_strikes.yml",
                    "archery_skill_shot.yml")) {
                try (InputStream in = plugin.getResource("talents/" + name)) {
                    if (in == null) {
                        continue;
                    }
                    loadFile(YamlConfiguration.loadConfiguration(new InputStreamReader(in, StandardCharsets.UTF_8)));
                } catch (Exception ex) {
                    plugin.getLogger().warning("Classpath talent " + name + ": " + ex.getMessage());
                }
            }
        }
        plugin.getLogger().info("Loaded " + talents.size() + " talents");
    }

    public void reload() {
        load();
    }

    @SuppressWarnings("unchecked")
    private void loadFile(YamlConfiguration yaml) {
        String id = yaml.getString("id");
        if (id == null || id.isBlank()) {
            return;
        }
        Optional<SkillId> skill = SkillId.fromString(yaml.getString("skill", ""));
        if (skill.isEmpty()) {
            plugin.getLogger().warning("Talent " + id + " missing skill");
            return;
        }
        List<String> triggers = yaml.getStringList("triggers");
        List<Map<String, Object>> effects = new ArrayList<>();
        List<?> rawEffects = yaml.getList("effects");
        if (rawEffects != null) {
            for (Object o : rawEffects) {
                if (o instanceof Map<?, ?> m) {
                    Map<String, Object> map = new HashMap<>();
                    m.forEach((k, v) -> map.put(String.valueOf(k), v));
                    effects.add(map);
                } else if (o instanceof ConfigurationSection sec) {
                    effects.add(sec.getValues(false));
                }
            }
        }
        List<Map<String, Object>> conditions = new ArrayList<>();
        List<?> rawCond = yaml.getList("conditions");
        if (rawCond != null) {
            for (Object o : rawCond) {
                if (o instanceof Map<?, ?> m) {
                    Map<String, Object> map = new HashMap<>();
                    m.forEach((k, v) -> map.put(String.valueOf(k), v));
                    conditions.add(map);
                }
            }
        }
        int unlock = yaml.getInt("unlock-level", yaml.getInt("required_level", 1));
        TalentDefinition def = new TalentDefinition(
                id,
                yaml.getString("display-name", id),
                yaml.getString("description", ""),
                skill.get(),
                unlock,
                yaml.getInt("max-rank", 1),
                yaml.getDouble("mana-cost", 0),
                yaml.getInt("cooldown-seconds", 0),
                yaml.getInt("duration-seconds", 0),
                triggers,
                effects,
                conditions);
        talents.put(id.toLowerCase(Locale.ROOT), def);
    }

    public Collection<TalentDefinition> all() {
        return talents.values();
    }

    public Optional<TalentDefinition> get(String id) {
        if (id == null) {
            return Optional.empty();
        }
        return Optional.ofNullable(talents.get(id.toLowerCase(Locale.ROOT)));
    }

    public void unlockByLevel(PlayerSkillsProfile profile) {
        if (profile == null || !plugin.getConfig().getBoolean("features.talents", true)) {
            return;
        }
        boolean changed = false;
        for (TalentDefinition def : talents.values()) {
            int level = profile.skill(def.skill()).level();
            if (level >= def.unlockLevel()) {
                TalentState state = profile.talent(def.id());
                if (!state.unlocked()) {
                    state.setUnlocked(true);
                    if (state.rank() <= 0) {
                        state.setRank(1);
                    }
                    changed = true;
                }
            }
        }
        if (changed) {
            profile.markDirty();
            plugin.repository().saveAsync(profile);
        }
    }

    public void handleTrigger(Player player, String triggerId, Map<String, Object> context) {
        if (player == null || triggerId == null || !plugin.getConfig().getBoolean("features.talents", true)) {
            return;
        }
        PlayerSkillsProfile profile = plugin.repository().getOrCreate(player.getUniqueId());
        long now = System.currentTimeMillis();
        for (TalentDefinition def : talents.values()) {
            if (!def.triggers().contains(triggerId)) {
                continue;
            }
            TalentState state = profile.talent(def.id());
            if (!state.unlocked()) {
                continue;
            }
            // Passive/combat triggers require equipped; activate trigger can run if unlocked
            boolean activate = "on_ability_activate".equals(triggerId);
            if (!activate && !state.equipped()) {
                continue;
            }
            if (state.onCooldown(now)) {
                continue;
            }
            if (!plugin.conditionEval().matches(player, def.conditions(), context)) {
                continue;
            }
            RootSkillsTalentTriggerEvent event =
                    new RootSkillsTalentTriggerEvent(player, def.id(), triggerId);
            Bukkit.getPluginManager().callEvent(event);
            if (event.isCancelled()) {
                continue;
            }
            if (def.manaCost() > 0 && !plugin.manaManager().spend(profile, def.manaCost())) {
                player.sendMessage(plugin.colorize("&cNot enough mana."));
                continue;
            }
            plugin.effectRunner().run(player, def.effects(), context, def);
            if (def.cooldownSeconds() > 0) {
                long until = now + def.cooldownSeconds() * 1000L;
                state.setCooldownUntilMs(until);
                plugin.cooldownService().start(player.getUniqueId(), def.id(), until);
            }
            if (def.durationSeconds() > 0 && plugin.abilitySessions() != null) {
                for (Map<String, Object> effect : def.effects()) {
                    String eid = String.valueOf(effect.getOrDefault("id", ""));
                    plugin.abilitySessions().start(player.getUniqueId(), eid, def.durationSeconds() * 1000L);
                }
            }
            profile.markDirty();
            player.sendMessage(plugin.msg("talents.triggered").replace("{talent}", def.displayName()));
        }
    }

    public boolean activateAbility(Player player, String talentId) {
        Optional<TalentDefinition> def = get(talentId);
        if (def.isEmpty()) {
            return false;
        }
        Map<String, Object> ctx = new HashMap<>();
        ctx.put("talent", talentId);
        handleTrigger(player, "on_ability_activate", ctx);
        return true;
    }
}

