package com.rootrecord.minecraft.rootskills.engine;

import org.bukkit.entity.Player;

import java.util.List;
import java.util.Map;

public final class ConditionEval {

    public boolean matches(Player player, List<Map<String, Object>> conditions, Map<String, Object> context) {
        if (conditions == null || conditions.isEmpty()) {
            return true;
        }
        for (Map<String, Object> cond : conditions) {
            String type = String.valueOf(cond.getOrDefault("type", cond.getOrDefault("id", ""))).toLowerCase();
            switch (type) {
                case "sneaking" -> {
                    if (player == null || !player.isSneaking()) {
                        return false;
                    }
                }
                case "chance" -> {
                    double chance = toDouble(cond.get("value"), toDouble(cond.get("chance"), 1.0));
                    if (Math.random() > chance) {
                        return false;
                    }
                }
                case "min_mana" -> {
                    // evaluated by caller usually; soft pass
                }
                default -> {
                    // unknown conditions pass
                }
            }
        }
        return true;
    }

    private static double toDouble(Object o, double def) {
        if (o instanceof Number n) {
            return n.doubleValue();
        }
        if (o != null) {
            try {
                return Double.parseDouble(o.toString());
            } catch (NumberFormatException ignored) {
            }
        }
        return def;
    }
}

package com.rootrecord.minecraft.rootskills.engine;

import com.rootrecord.minecraft.rootskills.RootSkillsPlugin;
import com.rootrecord.minecraft.rootskills.talents.TalentDefinition;
import org.bukkit.Bukkit;
import org.bukkit.Location;
import org.bukkit.Particle;
import org.bukkit.Sound;
import org.bukkit.attribute.Attribute;
import org.bukkit.entity.Player;
import org.bukkit.inventory.ItemStack;
import org.bukkit.inventory.meta.Damageable;
import org.bukkit.inventory.meta.ItemMeta;
import org.bukkit.potion.PotionEffect;
import org.bukkit.potion.PotionEffectType;

import java.util.List;
import java.util.Locale;
import java.util.Map;

public final class EffectRunner {

    private final RootSkillsPlugin plugin;

    public EffectRunner(RootSkillsPlugin plugin) {
        this.plugin = plugin;
    }

    public void run(Player player, List<Map<String, Object>> effects, Map<String, Object> context) {
        run(player, effects, context, null);
    }

    public void run(
            Player player,
            List<Map<String, Object>> effects,
            Map<String, Object> context,
            TalentDefinition talent) {
        if (player == null || effects == null || effects.isEmpty()) {
            return;
        }
        int rank = 1;
        if (talent != null) {
            rank = Math.max(1, plugin.repository().getOrCreate(player.getUniqueId()).talent(talent.id()).rank());
        }
        for (Map<String, Object> effect : effects) {
            apply(player, effect, context, rank, talent);
        }
    }

    private void apply(
            Player player,
            Map<String, Object> effect,
            Map<String, Object> context,
            int rank,
            TalentDefinition talent) {
        String id = String.valueOf(effect.getOrDefault("id", "")).trim().toUpperCase(Locale.ROOT)
                .replace('-', '_');
        switch (id) {
            case "MESSAGE" -> player.sendMessage(plugin.colorize(String.valueOf(effect.getOrDefault("text", ""))));
            case "SOUND" -> {
                try {
                    Sound sound = Sound.valueOf(String.valueOf(effect.getOrDefault("sound", "ENTITY_PLAYER_LEVELUP")));
                    player.playSound(player.getLocation(), sound, 1f, 1f);
                } catch (IllegalArgumentException ignored) {
                }
            }
            case "PARTICLE" -> {
                try {
                    Particle particle = Particle.valueOf(String.valueOf(effect.getOrDefault("particle", "CRIT")));
                    Location loc = player.getLocation().add(0, 1, 0);
                    player.getWorld().spawnParticle(particle, loc, toInt(effect.get("count"), 20), 0.4, 0.5, 0.4, 0.01);
                } catch (IllegalArgumentException ignored) {
                }
            }
            case "POTION" -> {
                PotionEffectType type = PotionEffectType.getByName(
                        String.valueOf(effect.getOrDefault("potion", "SPEED")));
                if (type != null) {
                    int duration = toInt(effect.get("duration"), 100);
                    int amplifier = toInt(effect.get("amplifier"), 0);
                    player.addPotionEffect(new PotionEffect(type, duration, amplifier));
                }
            }
            case "DAMAGE_BONUS", "DAMAGE_BONUS".replace('_', '_') -> {
                // Flag for combat listeners via ability session
                double amount = toDouble(effect.get("amount"), toDouble(effect.get("amount-per-rank"), 1.0) * rank);
                if (plugin.abilitySessions() != null) {
                    plugin.abilitySessions().setFlag(player.getUniqueId(), "damage_bonus", amount, 5000L);
                }
            }
            case "DECREASE_DAMAGE", "DAMAGE_REDUCTION" -> {
                double amount = toDouble(effect.get("amount"), 0.1);
                if (plugin.abilitySessions() != null) {
                    plugin.abilitySessions().setFlag(player.getUniqueId(), "decrease_damage", amount, 5000L);
                }
            }
            case "HEAL" -> {
                double amount = toDouble(effect.get("amount"), 2.0);
                double max = player.getAttribute(Attribute.MAX_HEALTH) != null
                        ? player.getAttribute(Attribute.MAX_HEALTH).getValue()
                        : 20.0;
                player.setHealth(Math.min(max, player.getHealth() + amount));
            }
            case "GIVE_ITEM_DURABILITY" -> {
                ItemStack hand = player.getInventory().getItemInMainHand();
                if (hand != null && hand.hasItemMeta()) {
                    ItemMeta meta = hand.getItemMeta();
                    if (meta instanceof Damageable d) {
                        int repair = toInt(effect.get("amount"), 10);
                        d.setDamage(Math.max(0, d.getDamage() - repair));
                        hand.setItemMeta(meta);
                    }
                }
            }
            case "BREAK_BONUS", "DOUBLE_DROP" -> {
                if (plugin.abilitySessions() != null) {
                    long dur = talent != null ? talent.durationSeconds() * 1000L : 10_000L;
                    plugin.abilitySessions().start(player.getUniqueId(), "break_bonus", Math.max(1000L, dur));
                }
            }
            case "SPEED_BURST", "SPEED", "HASTE" -> {
                int duration = toInt(effect.get("duration"),
                        talent != null ? talent.durationSeconds() * 20 : 100);
                int amp = toInt(effect.get("amplifier"), 1);
                PotionEffectType type = id.contains("HASTE") ? PotionEffectType.HASTE : PotionEffectType.SPEED;
                player.addPotionEffect(new PotionEffect(type, duration, amp));
            }
            case "SUPER_BREAKER", "GIGA_DRILL", "TREE_FELLER", "SERRATED_STRIKES" -> {
                long dur = talent != null ? talent.durationSeconds() * 1000L : 15_000L;
                if (plugin.abilitySessions() != null) {
                    plugin.abilitySessions().start(player.getUniqueId(), id.toLowerCase(Locale.ROOT), dur);
                }
                player.addPotionEffect(new PotionEffect(PotionEffectType.HASTE, (int) (dur / 50), 2));
                player.sendMessage(plugin.colorize("&eAbility active: &6" + id.toLowerCase(Locale.ROOT)));
            }
            case "XP_BONUS" -> {
                double multiplier = toDouble(effect.get("multiplier"), 1.1);
                if (plugin.abilitySessions() != null) {
                    plugin.abilitySessions().setFlag(player.getUniqueId(), "xp_bonus", multiplier, 10_000L);
                }
            }
            case "MANA_RESTORE" -> plugin.manaManager().restore(
                    plugin.repository().getOrCreate(player.getUniqueId()),
                    toDouble(effect.get("amount"), 10));
            default -> plugin.getLogger().fine("Unknown effect: " + id);
        }
    }

    private static int toInt(Object o, int def) {
        if (o instanceof Number n) {
            return n.intValue();
        }
        if (o != null) {
            try {
                return Integer.parseInt(o.toString());
            } catch (NumberFormatException ignored) {
            }
        }
        return def;
    }

    private static double toDouble(Object o, double def) {
        if (o instanceof Number n) {
            return n.doubleValue();
        }
        if (o != null) {
            try {
                return Double.parseDouble(o.toString());
            } catch (NumberFormatException ignored) {
            }
        }
        return def;
    }
}

package com.rootrecord.minecraft.rootskills.engine;

import java.util.Map;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;

/** Tracks temporary ability flags / durations per player. */
public final class AbilitySessions {

    private final Map<UUID, Map<String, Long>> until = new ConcurrentHashMap<>();
    private final Map<UUID, Map<String, Double>> flags = new ConcurrentHashMap<>();

    public void start(UUID playerId, String abilityId, long durationMs) {
        if (playerId == null || abilityId == null) {
            return;
        }
        until.computeIfAbsent(playerId, id -> new ConcurrentHashMap<>())
                .put(abilityId.toLowerCase(), System.currentTimeMillis() + Math.max(0L, durationMs));
    }

    public boolean has(UUID playerId, String abilityId) {
        if (playerId == null || abilityId == null) {
            return false;
        }
        Map<String, Long> map = until.get(playerId);
        if (map == null) {
            return false;
        }
        Long end = map.get(abilityId.toLowerCase());
        if (end == null) {
            return false;
        }
        if (System.currentTimeMillis() > end) {
            map.remove(abilityId.toLowerCase());
            return false;
        }
        return true;
    }

    public void setFlag(UUID playerId, String key, double value, long durationMs) {
        start(playerId, key, durationMs);
        flags.computeIfAbsent(playerId, id -> new ConcurrentHashMap<>()).put(key.toLowerCase(), value);
    }

    public double flag(UUID playerId, String key, double def) {
        if (!has(playerId, key)) {
            return def;
        }
        Map<String, Double> map = flags.get(playerId);
        if (map == null) {
            return def;
        }
        return map.getOrDefault(key.toLowerCase(), def);
    }

    public void clear(UUID playerId) {
        if (playerId != null) {
            until.remove(playerId);
            flags.remove(playerId);
        }
    }
}

package com.rootrecord.minecraft.rootskills.mana;

import com.rootrecord.minecraft.rootskills.RootSkillsPlugin;
import com.rootrecord.minecraft.rootskills.model.PlayerSkillsProfile;
import org.bukkit.Bukkit;
import org.bukkit.entity.Player;
import org.bukkit.scheduler.BukkitTask;

import java.util.UUID;

public final class ManaManager {

    private final RootSkillsPlugin plugin;
    private BukkitTask regenTask;

    public ManaManager(RootSkillsPlugin plugin) {
        this.plugin = plugin;
    }

    public boolean enabled() {
        return plugin.getConfig().getBoolean("features.mana", true);
    }

    public void startRegenTask() {
        stop();
        if (!enabled()) {
            return;
        }
        double regen = plugin.getConfig().getDouble("mana.regen-per-second", 1.0);
        double max = plugin.getConfig().getDouble("mana.max", 100.0);
        regenTask = Bukkit.getScheduler().runTaskTimer(plugin, () -> {
            for (Player player : Bukkit.getOnlinePlayers()) {
                PlayerSkillsProfile profile = plugin.repository().find(player.getUniqueId()).orElse(null);
                if (profile == null) {
                    continue;
                }
                if (profile.maxMana() <= 0) {
                    profile.setMaxMana(max);
                }
                if (profile.mana() < profile.maxMana()) {
                    profile.setMana(Math.min(profile.maxMana(), profile.mana() + regen));
                }
            }
        }, 20L, 20L);
    }

    public void stop() {
        if (regenTask != null) {
            regenTask.cancel();
            regenTask = null;
        }
    }

    public void tickRegen(UUID playerId) {
        // handled by task
    }

    public boolean spend(PlayerSkillsProfile profile, double amount) {
        if (!enabled() || profile == null || amount <= 0) {
            return true;
        }
        if (profile.mana() < amount) {
            return false;
        }
        profile.setMana(profile.mana() - amount);
        return true;
    }

    public void restore(PlayerSkillsProfile profile, double amount) {
        if (!enabled() || profile == null || amount <= 0) {
            return;
        }
        profile.setMana(Math.min(profile.maxMana(), profile.mana() + amount));
    }

    public double getMana(UUID playerId) {
        return plugin.repository().getOrCreate(playerId).mana();
    }
}

package com.rootrecord.minecraft.rootskills.classes;

import com.rootrecord.minecraft.rootskills.RootSkillsPlugin;
import com.rootrecord.minecraft.rootskills.api.SkillId;
import org.bukkit.configuration.file.YamlConfiguration;

import java.io.File;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Optional;

public final class ClassManager {

    public record ClassDefinition(
            String id,
            String displayName,
            String description,
            List<String> primarySkills,
            Map<SkillId, Double> skillMultipliers) {}

    private final RootSkillsPlugin plugin;
    private final Map<String, ClassDefinition> classes = new LinkedHashMap<>();

    public ClassManager(RootSkillsPlugin plugin) {
        this.plugin = plugin;
    }

    public void load() {
        classes.clear();
        File dir = new File(plugin.getDataFolder(), "classes");
        if (!dir.exists()) {
            dir.mkdirs();
            plugin.saveResource("classes/warrior.yml", false);
            plugin.saveResource("classes/artisan.yml", false);
        }
        File[] files = dir.listFiles((d, n) -> n.endsWith(".yml"));
        if (files != null) {
            for (File f : files) {
                loadYaml(YamlConfiguration.loadConfiguration(f));
            }
        }
        if (classes.isEmpty()) {
            for (String name : List.of("warrior.yml", "artisan.yml")) {
                try (InputStream in = plugin.getResource("classes/" + name)) {
                    if (in != null) {
                        loadYaml(YamlConfiguration.loadConfiguration(
                                new InputStreamReader(in, StandardCharsets.UTF_8)));
                    }
                } catch (Exception ignored) {
                }
            }
        }
        plugin.getLogger().info("Loaded " + classes.size() + " classes");
    }

    private void loadYaml(YamlConfiguration yaml) {
        String id = yaml.getString("id");
        if (id == null) {
            return;
        }
        Map<SkillId, Double> mults = new HashMap<>();
        List<String> primary = yaml.getStringList("primary-skills");
        for (String s : primary) {
            SkillId.fromString(s).ifPresent(sk -> mults.put(sk, 1.25));
        }
        if (yaml.isConfigurationSection("skill-multipliers")) {
            for (String key : yaml.getConfigurationSection("skill-multipliers").getKeys(false)) {
                SkillId.fromString(key).ifPresent(sk ->
                        mults.put(sk, yaml.getDouble("skill-multipliers." + key, 1.0)));
            }
        }
        classes.put(id.toLowerCase(Locale.ROOT), new ClassDefinition(
                id.toLowerCase(Locale.ROOT),
                yaml.getString("display-name", id),
                yaml.getString("description", ""),
                primary,
                mults));
    }

    public void reload() {
        load();
    }

    public boolean enabled() {
        return plugin.getConfig().getBoolean("features.classes", true);
    }

    public Optional<ClassDefinition> get(String id) {
        if (id == null) {
            return Optional.empty();
        }
        return Optional.ofNullable(classes.get(id.toLowerCase(Locale.ROOT)));
    }

    public Map<String, ClassDefinition> all() {
        return classes;
    }

    public double skillXpMultiplier(String classId, SkillId skill) {
        if (classId == null || skill == null) {
            return 1.0;
        }
        return get(classId).map(c -> c.skillMultipliers().getOrDefault(skill, 1.0)).orElse(1.0);
    }

    public boolean select(java.util.UUID playerId, String classId) {
        Optional<ClassDefinition> def = get(classId);
        if (def.isEmpty()) {
            return false;
        }
        var profile = plugin.repository().getOrCreate(playerId);
        profile.setClassId(def.get().id());
        plugin.repository().saveAsync(profile);
        return true;
    }
}

package com.rootrecord.minecraft.rootskills.prestige;

import com.rootrecord.minecraft.rootskills.RootSkillsPlugin;
import com.rootrecord.minecraft.rootskills.api.SkillId;
import com.rootrecord.minecraft.rootskills.api.events.RootSkillsPrestigeEvent;
import com.rootrecord.minecraft.rootskills.model.PlayerSkillsProfile;
import com.rootrecord.minecraft.rootskills.model.SkillProgress;
import org.bukkit.Bukkit;
import org.bukkit.entity.Player;

public final class PrestigeManager {

    private final RootSkillsPlugin plugin;

    public PrestigeManager(RootSkillsPlugin plugin) {
        this.plugin = plugin;
    }

    public boolean enabled() {
        return plugin.getConfig().getBoolean("features.prestige", true);
    }

    public int threshold() {
        return plugin.getConfig().getInt("prestige-threshold", 1000);
    }

    public boolean canPrestige(PlayerSkillsProfile profile, SkillId skill) {
        if (!enabled() || profile == null || skill == null) {
            return false;
        }
        return profile.skill(skill).level() >= threshold();
    }

    public boolean prestige(PlayerSkillsProfile profile, SkillId skill) {
        if (!canPrestige(profile, skill)) {
            return false;
        }
        SkillProgress progress = profile.skill(skill);
        int old = progress.prestige();
        progress.setPrestige(old + 1);
        progress.setLevel(0);
        progress.setXp(0L);
        double buffPer = plugin.getConfig().getDouble("prestige.buff-per-prestige", 0.05);
        progress.setPrestigeBuff(1.0 + (buffPer * progress.prestige()));
        profile.markDirty();
        plugin.repository().saveAsync(profile);

        Player player = Bukkit.getPlayer(profile.playerId());
        if (player != null) {
            Bukkit.getPluginManager().callEvent(
                    new RootSkillsPrestigeEvent(player, skill, old, progress.prestige()));
            player.sendMessage(plugin.msg("prestige.done")
                    .replace("{skill}", skill.key())
                    .replace("{prestige}", Integer.toString(progress.prestige())));
        }
        return true;
    }
}

