import java.util.concurrent.ConcurrentHashMap;

public final class BoosterManager {

    public record BoosterOffer(String id, String displayName, double multiplier, long durationMs, double price) {}

    private final RootSkillsPlugin plugin;
    private final Map<UUID, Map<String, ActiveBooster>> active = new ConcurrentHashMap<>();
    private Economy economy;

    public record ActiveBooster(String id, SkillId skill, double multiplier, long expiresAt) {}

    public BoosterManager(RootSkillsPlugin plugin) {
        this.plugin = plugin;
    }

    public void init() {
        if (Bukkit.getPluginManager().getPlugin("Vault") != null) {
            RegisteredServiceProvider<Economy> rsp =
                    Bukkit.getServicesManager().getRegistration(Economy.class);
            if (rsp != null) {
                economy = rsp.getProvider();
            }
        }
    }

    public boolean enabled() {
        return plugin.getConfig().getBoolean("features.boosters", true);
    }

    public double xpMultiplier(UUID playerId, SkillId skill) {
        if (!enabled() || playerId == null) {
            return 1.0;
        }
        prune(playerId);
        Map<String, ActiveBooster> map = active.get(playerId);
        if (map == null || map.isEmpty()) {
            return 1.0;
        }
        double mult = 1.0;
        long now = System.currentTimeMillis();
        for (ActiveBooster b : map.values()) {
            if (b.expiresAt() < now) {
                continue;
            }
            if (b.skill() == null || b.skill() == skill) {
                mult *= b.multiplier();
            }
        }
        return mult;
    }

    public void grant(UUID playerId, String boosterId, SkillId skill, double multiplier, long durationMs) {
        long expires = System.currentTimeMillis() + durationMs;
        active.computeIfAbsent(playerId, id -> new ConcurrentHashMap<>())
                .put(boosterId, new ActiveBooster(boosterId, skill, multiplier, expires));
        persist(playerId, boosterId, skill, multiplier, expires);
    }

    public boolean buy(Player player, String boosterId) {
        if (!enabled() || player == null) {
            return false;
        }
        BoosterOffer offer = offer(boosterId);
        if (offer == null) {
            return false;
        }
        if (economy != null) {
            if (!economy.has(player, offer.price())) {
                player.sendMessage(plugin.colorize("&cNot enough Gold."));
                return false;
            }
            economy.withdrawPlayer(player, offer.price());
        }
        grant(player.getUniqueId(), offer.id(), null, offer.multiplier(), offer.durationMs());
        player.sendMessage(plugin.colorize("&aBooster activated: &e" + offer.displayName()));
        return true;
    }

    public BoosterOffer offer(String id) {
        if (id == null) {
            return null;
        }
        // Built-in offers; config can override later
        return switch (id.toLowerCase()) {
            case "xp2" -> new BoosterOffer("xp2", "2x XP (1h)", 2.0, 3_600_000L, 500);
            case "xp15" -> new BoosterOffer("xp15", "1.5x XP (30m)", 1.5, 1_800_000L, 200);
            default -> null;
        };
    }

    private void prune(UUID playerId) {
        Map<String, ActiveBooster> map = active.get(playerId);
        if (map == null) {
            return;
        }
        long now = System.currentTimeMillis();
        map.entrySet().removeIf(e -> e.getValue().expiresAt() < now);
    }

    private void persist(UUID playerId, String boosterId, SkillId skill, double multiplier, long expires) {
        if (plugin.database() == null || !plugin.database().available()) {
            return;
        }
        Bukkit.getScheduler().runTaskAsynchronously(plugin, () -> {
            try (Connection c = plugin.database().connection();
                 PreparedStatement ps = c.prepareStatement(
                         "INSERT INTO " + plugin.schemaManager().table("boosters")
                                 + " (uuid, booster_id, skill_id, multiplier, expires_at) VALUES (?,?,?,?,?)"
                                 + " ON DUPLICATE KEY UPDATE skill_id=VALUES(skill_id),"
                                 + " multiplier=VALUES(multiplier), expires_at=VALUES(expires_at)")) {
                ps.setString(1, playerId.toString());
                ps.setString(2, boosterId);
                ps.setString(3, skill == null ? null : skill.key());
                ps.setDouble(4, multiplier);
                ps.setLong(5, expires);
                ps.executeUpdate();
            } catch (Exception ex) {
                plugin.getLogger().warning("Booster persist failed: " + ex.getMessage());
            }
        });
    }

    public void loadPlayer(UUID playerId) {
        if (plugin.database() == null || !plugin.database().available()) {
            return;
        }
        Bukkit.getScheduler().runTaskAsynchronously(plugin, () -> {
            try (Connection c = plugin.database().connection();
                 PreparedStatement ps = c.prepareStatement(
                         "SELECT booster_id, skill_id, multiplier, expires_at FROM "
                                 + plugin.schemaManager().table("boosters")
                                 + " WHERE uuid=? AND expires_at > ?")) {
                ps.setString(1, playerId.toString());
                ps.setLong(2, System.currentTimeMillis());
                try (ResultSet rs = ps.executeQuery()) {
                    Map<String, ActiveBooster> map = new ConcurrentHashMap<>();
                    while (rs.next()) {
                        String skillRaw = rs.getString("skill_id");
                        SkillId skill = skillRaw == null ? null : SkillId.fromString(skillRaw).orElse(null);
                        map.put(rs.getString("booster_id"), new ActiveBooster(
                                rs.getString("booster_id"),
                                skill,
                                rs.getDouble("multiplier"),
                                rs.getLong("expires_at")));
                    }
                    if (!map.isEmpty()) {
                        active.put(playerId, map);
                    }
                }
            } catch (Exception ex) {
                plugin.getLogger().warning("Booster load failed: " + ex.getMessage());
            }
        });
    }
}

package com.rootrecord.minecraft.rootskills.party;

import com.rootrecord.minecraft.rootskills.RootSkillsPlugin;
import com.rootrecord.minecraft.rootskills.api.SkillId;
import com.rootrecord.minecraft.rootskills.model.Party;
import com.rootrecord.minecraft.rootskills.model.PlayerSkillsProfile;
import org.bukkit.Bukkit;
import org.bukkit.entity.Player;

import java.sql.Connection;
import java.sql.PreparedStatement;
import java.util.Map;
import java.util.Optional;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;

public final class PartyManager {

    private final RootSkillsPlugin plugin;
    private final Map<UUID, Party> parties = new ConcurrentHashMap<>();
    private final Map<UUID, UUID> memberToParty = new ConcurrentHashMap<>();
    private final Map<UUID, UUID> invites = new ConcurrentHashMap<>();

    public PartyManager(RootSkillsPlugin plugin) {
        this.plugin = plugin;
    }

    public boolean enabled() {
        return plugin.getConfig().getBoolean("features.parties", true);
    }

    public double defaultXpShare() {
        return plugin.getConfig().getDouble("party.xp-share", 0.25);
    }

    public double shareRadius() {
        return plugin.getConfig().getDouble("party.share-radius", 50.0);
    }

    public Optional<Party> get(UUID partyId) {
        return Optional.ofNullable(parties.get(partyId));
    }

    public Optional<Party> partyOf(UUID playerId) {
        UUID partyId = memberToParty.get(playerId);
        return partyId == null ? Optional.empty() : get(partyId);
    }

    public Party create(UUID leaderId, String name) {
        Party party = new Party(UUID.randomUUID(), leaderId);
        party.setXpSharePercent(defaultXpShare());
        parties.put(party.id(), party);
        memberToParty.put(leaderId, party.id());
        PlayerSkillsProfile profile = plugin.repository().getOrCreate(leaderId);
        profile.setPartyId(party.id());
        plugin.repository().saveAsync(profile);
        persistParty(party, name);
        return party;
    }

    public boolean invite(UUID leaderId, UUID targetId) {
        Optional<Party> party = partyOf(leaderId);
        if (party.isEmpty() || !leaderId.equals(party.get().leaderId())) {
            return false;
        }
        invites.put(targetId, party.get().id());
        return true;
    }

    public boolean accept(UUID playerId) {
        UUID partyId = invites.remove(playerId);
        if (partyId == null) {
            return false;
        }
        Party party = parties.get(partyId);
        if (party == null || !party.add(playerId)) {
            return false;
        }
        memberToParty.put(playerId, partyId);
        plugin.repository().getOrCreate(playerId).setPartyId(partyId);
        plugin.repository().saveAsync(plugin.repository().getOrCreate(playerId));
        persistMember(partyId, playerId);
        return true;
    }

    public void leave(UUID playerId) {
        UUID partyId = memberToParty.remove(playerId);
        if (partyId == null) {
            return;
        }
        Party party = parties.get(partyId);
        if (party != null) {
            party.remove(playerId);
            if (party.members().isEmpty() || playerId.equals(party.leaderId())) {
                disband(partyId);
            }
        }
        PlayerSkillsProfile profile = plugin.repository().getOrCreate(playerId);
        profile.setPartyId(null);
        plugin.repository().saveAsync(profile);
    }

    public void disband(UUID partyId) {
        Party party = parties.remove(partyId);
        if (party == null) {
            return;
        }
        for (UUID member : party.members()) {
            memberToParty.remove(member, partyId);
            PlayerSkillsProfile profile = plugin.repository().getOrCreate(member);
            profile.setPartyId(null);
            plugin.repository().saveAsync(profile);
        }
    }

    public void shareXp(Player source, SkillId skill, long amount) {
        if (!enabled() || source == null || amount <= 0) {
            return;
        }
        Optional<Party> partyOpt = partyOf(source.getUniqueId());
        if (partyOpt.isEmpty()) {
            return;
        }
        Party party = partyOpt.get();
        double share = party.xpSharePercent() > 0 ? party.xpSharePercent() : defaultXpShare();
        long shared = Math.max(1L, (long) Math.floor(amount * share));
        double radiusSq = shareRadius() * shareRadius();
        for (UUID memberId : party.members()) {
            if (memberId.equals(source.getUniqueId())) {
                continue;
            }
            Player member = Bukkit.getPlayer(memberId);
            if (member == null || !member.getWorld().equals(source.getWorld())) {
                continue;
            }
            if (member.getLocation().distanceSquared(source.getLocation()) > radiusSq) {
                continue;
            }
            plugin.xpService().addXp(memberId, skill, shared, false);
        }
    }

    private void persistParty(Party party, String name) {
        if (plugin.database() == null || !plugin.database().available()) {
            return;
        }
        Bukkit.getScheduler().runTaskAsynchronously(plugin, () -> {
            try (Connection c = plugin.database().connection();
                 PreparedStatement ps = c.prepareStatement(
                         "INSERT INTO " + plugin.schemaManager().table("parties")
                                 + " (party_id, leader_uuid, name, xp_share) VALUES (?,?,?,?)"
                                 + " ON DUPLICATE KEY UPDATE leader_uuid=VALUES(leader_uuid),"
                                 + " name=VALUES(name), xp_share=VALUES(xp_share)")) {
                ps.setString(1, party.id().toString());
                ps.setString(2, party.leaderId().toString());
                ps.setString(3, name);
                ps.setDouble(4, party.xpSharePercent());
                ps.executeUpdate();
                persistMember(party.id(), party.leaderId());
            } catch (Exception ex) {
                plugin.getLogger().warning("Party persist failed: " + ex.getMessage());
            }
        });
    }

    private void persistMember(UUID partyId, UUID playerId) {
        if (plugin.database() == null || !plugin.database().available()) {
            return;
        }
        Bukkit.getScheduler().runTaskAsynchronously(plugin, () -> {
            try (Connection c = plugin.database().connection();
                 PreparedStatement ps = c.prepareStatement(
                         "INSERT IGNORE INTO " + plugin.schemaManager().table("party_members")
                                 + " (party_id, uuid) VALUES (?,?)")) {
                ps.setString(1, partyId.toString());
                ps.setString(2, playerId.toString());
                ps.executeUpdate();
            } catch (Exception ex) {
                plugin.getLogger().warning("Party member persist failed: " + ex.getMessage());
            }
        });
    }
}

package com.rootrecord.minecraft.rootskills.gui;

import com.rootrecord.minecraft.rootskills.RootSkillsPlugin;
import com.rootrecord.minecraft.rootskills.api.SkillId;
import com.rootrecord.minecraft.rootskills.model.PlayerSkillsProfile;
import com.rootrecord.minecraft.rootskills.model.SkillProgress;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import net.kyori.adventure.text.format.TextDecoration;
import org.bukkit.Bukkit;
import org.bukkit.Material;
import org.bukkit.entity.Player;
import org.bukkit.event.EventHandler;
import org.bukkit.event.Listener;
import org.bukkit.event.inventory.InventoryClickEvent;
import org.bukkit.inventory.Inventory;
import org.bukkit.inventory.ItemStack;
import org.bukkit.inventory.meta.ItemMeta;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;

public final class SkillsHubGui implements Listener {

    private static final String TITLE = "Root Skills";

    private final RootSkillsPlugin plugin;
    private final Map<UUID, SkillId> openDetail = new HashMap<>();

    public SkillsHubGui(RootSkillsPlugin plugin) {
        this.plugin = plugin;
    }

    public void register() {
        plugin.getServer().getPluginManager().registerEvents(this, plugin);
    }

    public void open(Player player) {
        if (player == null) {
            return;
        }
        Inventory inv = Bukkit.createInventory(player, 27, Component.text(TITLE, NamedTextColor.GOLD));
        PlayerSkillsProfile profile = plugin.repository().getOrCreate(player.getUniqueId());
        SkillId[] skills = SkillId.values();
        for (int i = 0; i < skills.length && i < 27; i++) {
            inv.setItem(i, skillIcon(skills[i], profile.skill(skills[i])));
        }
        openDetail.remove(player.getUniqueId());
        player.openInventory(inv);
    }

    public void openDetail(Player player, SkillId skill) {
        Inventory inv = Bukkit.createInventory(player, 27,
                Component.text(skill.key() + " details", NamedTextColor.YELLOW));
        PlayerSkillsProfile profile = plugin.repository().getOrCreate(player.getUniqueId());
        SkillProgress sp = profile.skill(skill);
        inv.setItem(13, skillIcon(skill, sp));
        ItemStack back = new ItemStack(Material.ARROW);
        ItemMeta meta = back.getItemMeta();
        meta.displayName(Component.text("Back", NamedTextColor.GRAY).decoration(TextDecoration.ITALIC, false));
        back.setItemMeta(meta);
        inv.setItem(22, back);

        if (plugin.prestigeManager().canPrestige(profile, skill)) {
            ItemStack prestige = new ItemStack(Material.NETHER_STAR);
            ItemMeta pm = prestige.getItemMeta();
            pm.displayName(Component.text("Prestige", NamedTextColor.LIGHT_PURPLE)
                    .decoration(TextDecoration.ITALIC, false));
            prestige.setItemMeta(pm);
            inv.setItem(16, prestige);
        }
        openDetail.put(player.getUniqueId(), skill);
        player.openInventory(inv);
    }

    private ItemStack skillIcon(SkillId skill, SkillProgress sp) {
        Material mat = iconFor(skill);
        ItemStack item = new ItemStack(mat);
        ItemMeta meta = item.getItemMeta();
        meta.displayName(Component.text(capitalize(skill.key()), NamedTextColor.GOLD)
                .decoration(TextDecoration.ITALIC, false));
        long next = plugin.xpService().formula().xpToNext(sp.level());
        long floor = plugin.xpService().formula().totalXpForLevel(sp.level());
        long into = Math.max(0L, sp.xp() - floor);
        List<Component> lore = new ArrayList<>();
        lore.add(Component.text("Level " + sp.level(), NamedTextColor.YELLOW)
                .decoration(TextDecoration.ITALIC, false));
        lore.add(Component.text("XP " + into + " / " + next, NamedTextColor.GRAY)
                .decoration(TextDecoration.ITALIC, false));
        lore.add(Component.text("Prestige " + sp.prestige(), NamedTextColor.LIGHT_PURPLE)
                .decoration(TextDecoration.ITALIC, false));
        lore.add(Component.text("Click for details", NamedTextColor.DARK_GRAY)
                .decoration(TextDecoration.ITALIC, false));
        meta.lore(lore);
        item.setItemMeta(meta);
        return item;
    }

    @EventHandler
    public void onClick(InventoryClickEvent event) {
        if (!(event.getWhoClicked() instanceof Player player)) {
            return;
        }
        Component title = event.getView().title();
        String plain = net.kyori.adventure.text.serializer.plain.PlainTextComponentSerializer.plainText()
                .serialize(title);
        if (!plain.equals(TITLE) && !plain.endsWith(" details")) {
            return;
        }
        event.setCancelled(true);
        ItemStack clicked = event.getCurrentItem();
        if (clicked == null || clicked.getType().isAir()) {
            return;
        }
        SkillId detail = openDetail.get(player.getUniqueId());
        if (detail != null) {
            if (clicked.getType() == Material.ARROW) {
                open(player);
                return;
            }
            if (clicked.getType() == Material.NETHER_STAR) {
                PlayerSkillsProfile profile = plugin.repository().getOrCreate(player.getUniqueId());
                if (plugin.prestigeManager().prestige(profile, detail)) {
                    openDetail(player, detail);
                } else {
                    player.sendMessage(plugin.msg("prestige.not-ready")
                            .replace("{threshold}", Integer.toString(plugin.prestigeManager().threshold())));
                }
                return;
            }
            return;
        }
        int slot = event.getRawSlot();
        SkillId[] skills = SkillId.values();
        if (slot >= 0 && slot < skills.length) {
            openDetail(player, skills[slot]);
        }
    }

    private static String capitalize(String s) {
        if (s == null || s.isEmpty()) {
            return s;
        }
        return Character.toUpperCase(s.charAt(0)) + s.substring(1);
    }

    private static Material iconFor(SkillId skill) {
        return switch (skill) {
            case MINING -> Material.IRON_PICKAXE;
            case WOODCUTTING -> Material.IRON_AXE;
            case HERBALISM -> Material.WHEAT;
            case EXCAVATION -> Material.IRON_SHOVEL;
            case FISHING -> Material.FISHING_ROD;
            case REPAIR -> Material.ANVIL;
            case SALVAGE -> Material.GRINDSTONE;
            case SMELTING -> Material.FURNACE;
            case ALCHEMY -> Material.BREWING_STAND;
            case TAMING -> Material.BONE;
            case ACROBATICS -> Material.FEATHER;
            case UNARMED -> Material.LEATHER;
            case SWORDS -> Material.IRON_SWORD;
            case AXES -> Material.DIAMOND_AXE;
            case ARCHERY -> Material.BOW;
            case CROSSBOWS -> Material.CROSSBOW;
            case TRIDENTS -> Material.TRIDENT;
            case MACES -> Material.MACE;
            case SPEARS -> Material.STICK;
            case DEFENSE -> Material.SHIELD;
            case ELYTRA -> Material.ELYTRA;
        };
    }
}

package com.rootrecord.minecraft.rootskills.gui;

import com.rootrecord.minecraft.rootskills.RootSkillsPlugin;
import com.rootrecord.minecraft.rootskills.model.PlayerSkillsProfile;
import com.rootrecord.minecraft.rootskills.model.TalentState;
import com.rootrecord.minecraft.rootskills.talents.TalentDefinition;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import net.kyori.adventure.text.format.TextDecoration;
import org.bukkit.Bukkit;
import org.bukkit.Material;
import org.bukkit.entity.Player;
import org.bukkit.event.EventHandler;
import org.bukkit.event.Listener;
import org.bukkit.event.inventory.InventoryClickEvent;
import org.bukkit.event.player.PlayerSwapHandItemsEvent;
import org.bukkit.inventory.Inventory;
import org.bukkit.inventory.ItemStack;
import org.bukkit.inventory.meta.ItemMeta;

import java.util.ArrayList;
import java.util.List;

/** SHIFT+F opens talent loadout; click to equip/unequip or activate. */
public final class TalentLoadoutGui implements Listener {

    private static final String TITLE = "Talent Loadout";

    private final RootSkillsPlugin plugin;

    public TalentLoadoutGui(RootSkillsPlugin plugin) {
        this.plugin = plugin;
    }

    public void register() {
        plugin.getServer().getPluginManager().registerEvents(this, plugin);
    }

    public void open(Player player) {
        Inventory inv = Bukkit.createInventory(player, 54, Component.text(TITLE, NamedTextColor.AQUA));
        PlayerSkillsProfile profile = plugin.repository().getOrCreate(player.getUniqueId());
        int slot = 0;
        for (TalentDefinition def : plugin.talentManager().all()) {
            if (slot >= 54) {
                break;
            }
            TalentState state = profile.talent(def.id());
            ItemStack item = new ItemStack(state.equipped() ? Material.LIME_DYE
                    : (state.unlocked() ? Material.YELLOW_DYE : Material.GRAY_DYE));
            ItemMeta meta = item.getItemMeta();
            meta.displayName(Component.text(def.displayName(), NamedTextColor.GOLD)
                    .decoration(TextDecoration.ITALIC, false));
            List<Component> lore = new ArrayList<>();
            lore.add(Component.text(def.description(), NamedTextColor.GRAY)
                    .decoration(TextDecoration.ITALIC, false));
            lore.add(Component.text("Skill: " + def.skill().key() + " @" + def.unlockLevel(), NamedTextColor.YELLOW)
                    .decoration(TextDecoration.ITALIC, false));
            lore.add(Component.text(state.unlocked() ? (state.equipped() ? "Equipped" : "Unlocked") : "Locked",
                            state.unlocked() ? NamedTextColor.GREEN : NamedTextColor.RED)
                    .decoration(TextDecoration.ITALIC, false));
            lore.add(Component.text("Left-click: equip/unequip", NamedTextColor.DARK_GRAY)
                    .decoration(TextDecoration.ITALIC, false));
            lore.add(Component.text("Right-click: activate", NamedTextColor.DARK_GRAY)
                    .decoration(TextDecoration.ITALIC, false));
            meta.lore(lore);
            // encode talent id in PDC-less way via localized name fallback: store in display lore last line
            item.setItemMeta(meta);
            // Use item amount + custom model isn't reliable; put id in persistent data
            item.editMeta(m -> m.getPersistentDataContainer().set(
                    plugin.talentKey(),
                    org.bukkit.persistence.PersistentDataType.STRING,
                    def.id()));
            inv.setItem(slot++, item);
        }
        player.openInventory(inv);
    }

    @EventHandler
    public void onSwap(PlayerSwapHandItemsEvent event) {
        if (!plugin.getConfig().getBoolean("features.talents", true)) {
            return;
        }
        if (!plugin.getConfig().getBoolean("talents.shift-f-loadout", true)) {
            return;
        }
        Player player = event.getPlayer();
        if (!player.isSneaking()) {
            return;
        }
        if (plugin.getConfig().getBoolean("talents.cancel-swap-on-loadout", true)) {
            event.setCancelled(true);
        }
        open(player);
    }

    @EventHandler
    public void onClick(InventoryClickEvent event) {
        if (!(event.getWhoClicked() instanceof Player player)) {
            return;
        }
        String plain = net.kyori.adventure.text.serializer.plain.PlainTextComponentSerializer.plainText()
                .serialize(event.getView().title());
        if (!TITLE.equals(plain)) {
            return;
        }
        event.setCancelled(true);
        ItemStack clicked = event.getCurrentItem();
        if (clicked == null || !clicked.hasItemMeta()) {
            return;
        }
        String talentId = clicked.getItemMeta().getPersistentDataContainer()
                .get(plugin.talentKey(), org.bukkit.persistence.PersistentDataType.STRING);
        if (talentId == null) {
            return;
        }
        PlayerSkillsProfile profile = plugin.repository().getOrCreate(player.getUniqueId());
        TalentState state = profile.talent(talentId);
        if (!state.unlocked()) {
            player.sendMessage(plugin.msg("talents.locked").replace("{talent}", talentId));
            return;
        }
        if (event.isRightClick()) {
            plugin.talentManager().activateAbility(player, talentId);
            return;
        }
        state.setEquipped(!state.equipped());
        if (state.equipped()) {
            state.setSlot(event.getRawSlot());
        } else {
            state.setSlot(-1);
        }
        profile.markDirty();
        plugin.repository().saveAsync(profile);
        open(player);
    }
}

package com.rootrecord.minecraft.rootskills.listener;

import com.rootrecord.minecraft.rootskills.RootSkillsPlugin;
import org.bukkit.event.EventHandler;
import org.bukkit.event.Listener;
import org.bukkit.event.player.PlayerJoinEvent;
import org.bukkit.event.player.PlayerQuitEvent;

public final class PlayerConnectionListener implements Listener {

    private final RootSkillsPlugin plugin;

    public PlayerConnectionListener(RootSkillsPlugin plugin) {
        this.plugin = plugin;
    }

    @EventHandler
    public void onJoin(PlayerJoinEvent event) {
        plugin.repository().loadAsync(event.getPlayer().getUniqueId(), event.getPlayer().getName(), () -> {
            if (plugin.boosterManager() != null) {
                plugin.boosterManager().loadPlayer(event.getPlayer().getUniqueId());
            }
            var profile = plugin.repository().getOrCreate(event.getPlayer().getUniqueId());
            if (profile.maxMana() <= 0 || profile.mana() <= 0 && profile.maxMana() > 0) {
                profile.setMaxMana(plugin.getConfig().getDouble("mana.max", 100));
                if (profile.mana() <= 0) {
                    profile.setMana(profile.maxMana());
                }
            }
        });
    }

    @EventHandler
    public void onQuit(PlayerQuitEvent event) {
        if (plugin.abilitySessions() != null) {
            plugin.abilitySessions().clear(event.getPlayer().getUniqueId());
        }
        if (plugin.cooldownService() != null) {
            plugin.cooldownService().clear(event.getPlayer().getUniqueId());
        }
        plugin.repository().unload(event.getPlayer().getUniqueId());
    }
}

